// Tisple ][ for VS Code: what the checker knows (semantic highlighting, hover, go to
// definition, references, outline and errors as you type, all from `tisple index`; see
// language.js), formatting through `tisple fmt`, and a command that builds the open program
// and runs it in the built-in Apple IIe. The TextMate grammar in syntaxes/, generated by
// `tisple gen-editors editors`, colours what the index has not reached yet.

const vscode = require("vscode");
const cp = require("child_process");
const fs = require("fs");
const os = require("os");
const path = require("path");
const ix = require("./index_client");
const language = require("./language");

// formats a copy in a temp file, so an unsaved buffer formats as it is
function formatDocument(doc) {
    const tool = ix.tisplePath(doc.fileName);
    const tmp = path.join(os.tmpdir(), `tisple-fmt-${process.pid}.tsp`);
    fs.writeFileSync(tmp, doc.getText());
    try {
        const out = cp.execFileSync(tool, ["fmt", tmp], { encoding: "utf8" });
        if (out === doc.getText()) {
            return [];
        }
        const all = new vscode.Range(doc.positionAt(0), doc.positionAt(doc.getText().length));
        return [vscode.TextEdit.replace(all, out)];
    } catch (e) {
        // a reader error: leave the text alone; the diagnostics show the error
        return [];
    } finally {
        fs.rmSync(tmp, { force: true });
    }
}

function runOnApple2() {
    const editor = vscode.window.activeTextEditor;
    if (!editor || editor.document.languageId !== "tisple") {
        vscode.window.showInformationMessage("Tisple: open a .tsp file first.");
        return;
    }
    const doc = editor.document;
    doc.save().then(() => {
        const tool = ix.tisplePath(doc.fileName);
        const q = (s) => `'${s.replace(/'/g, "'\\''")}'`;
        const terminal = vscode.window.terminals.find((t) => t.name === "Tisple ][") ||
            vscode.window.createTerminal("Tisple ][");
        terminal.show(true);
        terminal.sendText(`${q(tool)} run ${q(doc.fileName)}`);
    });
}

function activate(context) {
    language.register(context);
    context.subscriptions.push(vscode.languages.registerDocumentFormattingEditProvider(
        "tisple", { provideDocumentFormattingEdits: formatDocument }));
    context.subscriptions.push(vscode.commands.registerCommand("tisple.run", runOnApple2));
}

function deactivate() {}

module.exports = { activate, deactivate };
